   872
   873  static _cups_ps_obj_t   *               /* O - New object */
   874  index_stack(_cups_ps_stack_t *st,       /* I - Stack */
   875              int              n)         /* I - Object index */
   876  {
   877    if (n < 0 || (n = st->num_objs - n - 1) < 0)
   878      return (NULL);
   879
   880    return (push_stack(st, st->objs + n));
